const body = $input.first().json.body || $input.first().json;

const startupId = body.startupId || ('startup_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
const budget = body.budget || 500000;
const runway = body.runway || 12;

const state = {
  company: {
    name: body.name || 'Unnamed Startup',
    industry: body.industry || 'Tech',
    idea: body.idea || 'A brilliant product',
    phase: 'seed',
    budget: budget,
    burnRate: Math.round(budget / runway),
    runway: runway,
    mrr: Math.round(budget * 0.015),
    arr: Math.round(budget * 0.18),
    growth: 18,
    morale: 75,
    investorConfidence: 60,
    technicalDebt: 20,
    brandReputation: 45,
    productQuality: 55,
    marketFit: 40,
    teamSize: body.teamSize || 10,
    growthStrategy: body.growthStrategy || 'viral'
  },
  relationships: {
    'CEO-CTO': 'aligned',
    'CEO-PM': 'aligned',
    'CEO-Finance': 'neutral',
    'CEO-Marketing': 'aligned',
    'CTO-PM': 'tense',
    'Finance-Marketing': 'conflict'
  },
  influence: {
    CEO: 85, CTO: 70, PM: 60, Marketing: 55, Finance: 65, Investor: 90
  },
  // PERSONALITY VECTORS — drift each round based on outcomes
  personalityVectors: {
    CEO:       { riskTolerance: 75, aggressiveness: 80, optimism: 85, paranoia: 20, confidence: 80 },
    CTO:       { riskTolerance: 30, aggressiveness: 35, optimism: 40, paranoia: 60, confidence: 70 },
    PM:        { riskTolerance: 50, aggressiveness: 40, optimism: 65, paranoia: 35, confidence: 60 },
    Marketing: { riskTolerance: 70, aggressiveness: 75, optimism: 80, paranoia: 25, confidence: 70 },
    Finance:   { riskTolerance: 20, aggressiveness: 30, optimism: 30, paranoia: 70, confidence: 85 },
    Investor:  { riskTolerance: 50, aggressiveness: 60, optimism: 35, paranoia: 75, confidence: 90 }
  },
  // AGENT MEMORY — accumulates grudges, predictions, promises
  agentMemory: {
    CEO:       { recentConcerns: [], pastDecisions: [], currentStance: 'Optimistic, focused on growth', credibility: 75, wins: 0, losses: 0, failedPredictions: [], learnings: [] },
    CTO:       { recentConcerns: [], pastDecisions: [], currentStance: 'Worried about scaling too fast', credibility: 70, wins: 0, losses: 0, failedPredictions: [], warnings: [], learnings: [] },
    PM:        { recentConcerns: [], pastDecisions: [], currentStance: 'User needs are being ignored', credibility: 60, wins: 0, losses: 0, failedPredictions: [], learnings: [] },
    Marketing: { recentConcerns: [], pastDecisions: [], currentStance: 'Brand moment is now', credibility: 55, wins: 0, losses: 0, failedPredictions: [], learnings: [] },
    Finance:   { recentConcerns: [], pastDecisions: [], currentStance: 'Burn is too high, extend runway', credibility: 65, wins: 0, losses: 0, failedPredictions: [], budgetWarnings: [], learnings: [] },
    Investor:  { recentConcerns: [], pastDecisions: [], currentStance: 'Need proof of defensibility', credibility: 90, wins: 0, losses: 0, failedPredictions: [], learnings: [] }
  },
  // DELAYED CONSEQUENCE QUEUE — events scheduled to fire in future rounds
  delayedConsequences: [],
  roadmap: [],
  eventHistory: [],
  decisionHistory: [],
  simulationRound: 1,
  lastEvent: 'Company founded',
  status: 'OPERATING',
  startupId
};

const agentPrompt = `You are simulating a startup ecosystem.

COMPANY: ${state.company.name} — ${state.company.idea}
INDUSTRY: ${state.company.industry}
PHASE: ${state.company.phase}

CURRENT METRICS:
- Budget: $${state.company.budget.toLocaleString()}
- Runway: ${state.company.runway} months
- Burn Rate: $${state.company.burnRate.toLocaleString()}/mo
- Growth: ${state.company.growth}%
- Morale: ${state.company.morale}/100
- Investor Confidence: ${state.company.investorConfidence}/100
- Technical Debt: ${state.company.technicalDebt}/100
- Market Fit: ${state.company.marketFit}/100

TEAM RELATIONSHIPS:
${JSON.stringify(state.relationships, null, 2)}

EVENT: A new startup has been founded and the leadership team is meeting for the first time. React as your specific agent role. Establish your priorities and concerns for the company.`;

return [{ json: { startupId, worldState: state, agentPrompt, event: 'Company founded — first leadership meeting' } }];

const item = $input.first().json;
const { agentOutputs, rebuttalOutputs, worldState, event } = item;
const c = worldState.company || {};
const stanceSummary = agentOutputs.map(a => `${a.agent} (${a.stance}): ${a.summary}`).join('\n');
const rebuttalSummary = rebuttalOutputs.map(r => `${r.agent}: "${r.rebuttal}" escalation:${r.escalation}`).join('\n');
const pending = (worldState.delayedConsequences || []).map(dc => `Round ${dc.fireAtRound}: ${dc.description}`).join('\n');
const monthlyBurn = c.burnRate || 41667;
const minSpend = Math.round(monthlyBurn * 0.3);
const maxSpend = Math.round(monthlyBurn * 1.5);
const synthesisPrompt = `Decision Synthesizer — Recursive Startup war room.
COMPANY: ${c.name} | ROUND: ${worldState.simulationRound} | STATUS: ${worldState.status}
METRICS: budget $${(c.budget||0).toLocaleString()} | runway ${c.runway}mo | morale ${c.morale} | investor ${c.investorConfidence} | debt ${c.technicalDebt} | mrr $${(c.mrr||0).toLocaleString()}
EVENT: "${event}" | MARKET: ${worldState.marketSentiment || 'neutral'}

FINANCIAL CONSTRAINTS (enforce strictly):
- Monthly burn rate: $${monthlyBurn.toLocaleString()}
- Budget delta for worldStateUpdates.budget must be a NEGATIVE number between -$${minSpend.toLocaleString()} and -$${maxSpend.toLocaleString()} for a spending decision, or a POSITIVE number up to +$${Math.round(monthlyBurn*3).toLocaleString()} only if a funding event occurred.
- Do NOT model budget deltas in millions. This is a seed-stage company. A campaign costs $10K-$40K. A feature sprint costs $15K-$60K. An emergency hire costs $8K-$20K/mo added to burnRate.
- runway is recalculated automatically from budget/burnRate. Do NOT include runway in worldStateUpdates.
- Morale, investorConfidence, brandReputation, productQuality deltas must be between -15 and +15 per round.
- technicalDebt delta must be between -10 and +20 per round.
- growth delta must be between -10 and +25 per round.

WAVE 1:
${stanceSummary}
WAVE 2 REBUTTALS:
${rebuttalSummary}
PENDING DELAYED: ${pending || 'none'}
TASK: Determine winning/losing coalitions based on agent influence and argument strength. Output one concrete operational decision (not a vibe — a real action with a price). Apply metric deltas within the constraints above. Queue 1-2 delayed consequences (fireAtRound +2 to +4). Add personality deltas. Write a 2-sentence boardroom narrative. JSON only.`;
const passthrough = { agentOutputs, rebuttalOutputs, worldState, event, preRoundMetrics: { ...c }, isDemoMode: item.isDemoMode };
return [{ json: { ...item, synthesisPrompt, _passthrough: passthrough } }];

const item = $input.first().json;
const synthesis = typeof item.output === 'string' ? JSON.parse(item.output) : (item.output || item);
let passthrough = {};
try { const cr = $('Collect Rebuttals').first().json; if (cr.agentOutputs) passthrough = cr; } catch(e) {}
const worldState = passthrough.worldState || item.worldState || {};
const agentOutputs = passthrough.agentOutputs || item.agentOutputs || [];
const rebuttalOutputs = passthrough.rebuttalOutputs || item.rebuttalOutputs || [];
const preRoundMetrics = passthrough.preRoundMetrics || item.preRoundMetrics || JSON.parse(JSON.stringify(worldState.company || {}));
const isDemoMode = passthrough.isDemoMode || item.isDemoMode || false;
const startupId = worldState.startupId || item.startupId || passthrough.startupId;
const event = item.event || '';

if (!synthesis) throw new Error('Synthesis output missing — check Decision Synthesizer agent');

let updates = synthesis.worldStateUpdates || {};
const c = worldState.company || {};

// ── ENFORCE MAXIMUM SINGLE-ROUND SPEND ─────────────────────
const currentCash = c.budget || 0;
const burnRate = c.burnRate || 41667;

const absoluteMaxSpend = Math.min(
  Math.max(
    Math.round(currentCash * 0.10),
    Math.round(burnRate * 1.5)
  ),
  Math.round(currentCash * 0.20)
);

const requestedBudgetDelta = updates.budget || 0;

if (
  typeof updates.budget === 'number' &&
  updates.budget < -absoluteMaxSpend
) {
  updates = {
    ...updates,
    budget: -absoluteMaxSpend
  };
}

const appliedBudgetDelta = updates.budget || 0;
// ────────────────────────────────────────────────────────────

// Apply metric updates with clamping
const updatedCompany = {
  ...c,
  budget: Math.max(0, (c.budget || 0) + (updates.budget || 0)),
  burnRate: Math.max(5000, (c.burnRate || 40000) + (updates.burnRate || 0)),
  runway: Math.max(0, (c.runway || 0) + (updates.runway || 0)),
  mrr: Math.max(0, (c.mrr || 0) + (updates.mrr || 0)),
  growth: Math.max(-50, Math.min(300, (c.growth || 0) + (updates.growth || 0))),
  morale: Math.max(0, Math.min(100, (c.morale || 50) + (updates.morale || 0))),
  investorConfidence: Math.max(0, Math.min(100, (c.investorConfidence || 50) + (updates.investorConfidence || 0))),
  technicalDebt: Math.max(0, Math.min(100, (c.technicalDebt || 0) + (updates.technicalDebt || 0))),
  brandReputation: Math.max(0, Math.min(100, (c.brandReputation || 50) + (updates.brandReputation || 0))),
  productQuality: Math.max(0, Math.min(100, (c.productQuality || 50) + (updates.productQuality || 0))),
  marketFit: Math.max(0, Math.min(100, (c.marketFit || 40) + (updates.marketFit || 0))),
};

// Recalculate runway from budget/burnRate
if (updatedCompany.burnRate > 0) {
  updatedCompany.runway = Math.round(updatedCompany.budget / updatedCompany.burnRate);
}

// DELAYED CONSEQUENCE QUEUE — add new consequences from synthesis
const currentRound = worldState.simulationRound || 1;
const existingConsequences = worldState.delayedConsequences || [];
const newConsequences = (synthesis.delayedConsequences || []).map(c => ({
  ...c,
  queuedAtRound: currentRound
}));
const updatedDelayedConsequences = [...existingConsequences, ...newConsequences];

// PERSONALITY VECTOR DRIFT — apply deltas from synthesis
const personalityVectors = { ...(worldState.personalityVectors || {}) };
const pvDeltas = synthesis.personalityVectorDeltas || {};
Object.entries(pvDeltas).forEach(([agent, deltas]) => {
  if (personalityVectors[agent]) {
    Object.entries(deltas).forEach(([trait, delta]) => {
      if (personalityVectors[agent][trait] !== undefined) {
        personalityVectors[agent][trait] = Math.max(0, Math.min(100,
          personalityVectors[agent][trait] + delta
        ));
      }
    });
  }
});

// AGENT MEMORY UPDATE — track wins/losses/warnings/credibility
const agentMemory = JSON.parse(JSON.stringify(worldState.agentMemory || {}));
const winningCoalition = synthesis.winningCoalition || [];
const opposingCoalition = synthesis.opposingCoalition || [];

agentOutputs.forEach(agent => {
  const name = agent.agent;
  if (!agentMemory[name]) return;

  if (winningCoalition.includes(name)) {
    agentMemory[name].wins = (agentMemory[name].wins || 0) + 1;
    agentMemory[name].credibility = Math.min(100, (agentMemory[name].credibility || 50) + 5);
  } else if (opposingCoalition.includes(name)) {
    agentMemory[name].losses = (agentMemory[name].losses || 0) + 1;
    agentMemory[name].credibility = Math.max(0, (agentMemory[name].credibility || 50) - 3);
  }

  // Store agent's current concern as a warning for future reference
  if (agent.concerns && agent.concerns[0]) {
    if (!agentMemory[name].warnings) agentMemory[name].warnings = [];
    agentMemory[name].warnings.push(agent.concerns[0]);
    if (agentMemory[name].warnings.length > 5) agentMemory[name].warnings.shift();
  }

  agentMemory[name].currentStance = agent.summary || agentMemory[name].currentStance;
  agentMemory[name].recentConcerns = agent.concerns || [];
});

// Update influence based on win/loss patterns
const influence = { ...(worldState.influence || { CEO:85, CTO:70, PM:60, Marketing:55, Finance:65, Investor:90 }) };
winningCoalition.forEach(agent => {
  if (influence[agent] !== undefined) influence[agent] = Math.min(100, influence[agent] + 2);
});
opposingCoalition.forEach(agent => {
  if (influence[agent] !== undefined) influence[agent] = Math.max(10, influence[agent] - 2);
});

// Consequence propagation
let status = 'OPERATING';
const queuedEvents = [];

if (updatedCompany.runway <= 0) {
  status = 'BANKRUPT';
} else if (updatedCompany.runway <= 3) {
  status = 'CRITICAL';
  queuedEvents.push('runway_critical');
} else if (updatedCompany.morale <= 20) {
  status = 'CRITICAL';
  queuedEvents.push('morale_crisis');
  updatedCompany.teamSize = Math.max(1, (updatedCompany.teamSize || 10) - 1);
} else if (updatedCompany.investorConfidence <= 20) {
  queuedEvents.push('investor_alert');
} else if (updatedCompany.technicalDebt >= 80) {
  queuedEvents.push('technical_crisis');
} else if (updatedCompany.marketFit >= 75 && updatedCompany.growth >= 40) {
  updatedCompany.phase = 'series-a';
  queuedEvents.push('series_a_opportunity');
  status = 'OPERATING';
}

// Update relationships based on winning/losing coalitions
const relationships = { ...(worldState.relationships || {}) };
const degradeMap = { aligned: 'neutral', neutral: 'tense', tense: 'conflict', conflict: 'conflict' };
const improveMap = { conflict: 'tense', tense: 'neutral', neutral: 'aligned', aligned: 'aligned' };
for (let i = 0; i < winningCoalition.length - 1; i++) {
  const key = [winningCoalition[i], winningCoalition[i+1]].sort().join('-');
  if (relationships[key]) relationships[key] = improveMap[relationships[key]] || 'neutral';
}
for (const agent of opposingCoalition) {
  for (const winner of winningCoalition) {
    const key = [agent, winner].sort().join('-');
    if (relationships[key]) relationships[key] = degradeMap[relationships[key]] || 'tense';
  }
}

// Build new decision record
const decisionRecord = {
  id: 'dec_' + Date.now(),
  timestamp: new Date().toISOString(),
  round: worldState.simulationRound,
  decision: synthesis.decision,
  rationale: synthesis.rationale,
  winningCoalition: synthesis.winningCoalition || [],
  opposingCoalition: synthesis.opposingCoalition || [],
  keyTensions: synthesis.keyTensions || [],
  narrative: synthesis.simulationNarrative || '',
  rebuttalFeed: rebuttalOutputs.map(r => r.agent + ': ' + r.rebuttal),
  metricImpact: {
  ...updates,
  budget: appliedBudgetDelta
},

requestedMetricImpact: {
  ...synthesis.worldStateUpdates
},  
  delayedConsequencesQueued: newConsequences.length
};
// Investor pressure triggers
if (updatedCompany.investorConfidence <= 10) {
  queuedEvents.push('lead_investor_revolt');
} else if (updatedCompany.investorConfidence <= 20) {
  queuedEvents.push('bridge_round_required');
} else if (updatedCompany.investorConfidence <= 35) {
  queuedEvents.push('emergency_board_review');
}
const updatedState = {
  ...worldState,
  company: updatedCompany,
  relationships,
  influence,
  personalityVectors,
  agentMemory,
  delayedConsequences: updatedDelayedConsequences,
  roadmap: [...(worldState.roadmap || []), ...(synthesis.roadmapAdditions || []).map((r, i) => ({
    id: 'rm_' + Date.now() + i,
    title: r,
    status: 'planned',
    addedRound: worldState.simulationRound
  }))],
  eventHistory: [...(worldState.eventHistory || [])],
  decisionHistory: [...(worldState.decisionHistory || []), decisionRecord],
  simulationRound: (worldState.simulationRound || 1) + 1,
  lastEvent: event,
  status,
  startupId,
  pendingEvents: [                     // ← NEW FIELD
    ...(worldState.pendingEvents || []),
    ...queuedEvents
  ]
};

return [{
  json: {
    preRoundMetrics,
    rebuttalOutputs,
    isDemoMode,
    startupId,
    worldState: updatedState,
    lastDecision: synthesis.decision,
    rationale: synthesis.rationale,
    narrative: synthesis.simulationNarrative || '',
    rebuttalFeed: rebuttalOutputs.map(r => r.agent + ': ' + r.rebuttal),
    keyTensions: synthesis.keyTensions || [],
    winningCoalition: synthesis.winningCoalition || [],
    opposingCoalition: synthesis.opposingCoalition || [],
    agentVoices: agentOutputs,
    metrics: updatedCompany,
    relationships: updatedState.relationships,
    influence: updatedState.influence,
    personalityVectors: updatedState.personalityVectors,
    roadmap: updatedState.roadmap,
    event,
    simulationRound: updatedState.simulationRound,
    status,
    queuedEvents,
    delayedConsequences: updatedDelayedConsequences,
    consequenceFlags: synthesis.consequenceFlags || []
  }
}];

const DEMO_SCENARIOS = {
  competitor_50m: {
    event: 'Competitor NovaAI raises $50M Series B targeting your exact niche',
    oracleSkip: true, marketSentiment: 'bearish',
    preMetrics: { investorConfidence: 52, growth: 15 },
    relevanceHints: { primary: ['CEO','Marketing','Investor'], secondary: ['Finance'] },
    delayedQueue: [{ fireAtRound: 3, description: 'Competitor poaches two enterprise leads', metrics: { investorConfidence: -8, morale: -5 }, severity: 'medium', probability: 0.9 }]
  },
  infrastructure_collapse: {
    event: 'Product launch day — core API down 4 hours, 12K users affected',
    oracleSkip: true, marketSentiment: 'panic',
    preMetrics: { technicalDebt: 65, morale: 55, brandReputation: 40 },
    relevanceHints: { primary: ['CTO','CEO'], secondary: ['PM'] },
    delayedQueue: [{ fireAtRound: 2, description: 'Press picks up outage story', metrics: { brandReputation: -20, investorConfidence: -12 }, severity: 'high', probability: 0.95 }]
  },
  investor_revolt: {
    event: 'Lead investor demands emergency board meeting — threatens to pull next tranche',
    oracleSkip: true, marketSentiment: 'panic',
    preMetrics: { investorConfidence: 35, runway: 7 },
    relevanceHints: { primary: ['Investor','Finance','CEO'], secondary: [] }, delayedQueue: []
  },
  pr_disaster: {
    event: 'Viral tweet accuses your AI of bias — #BoycottTrending with 40K posts',
    oracleSkip: true, marketSentiment: 'bearish', preMetrics: { brandReputation: 35 },
    relevanceHints: { primary: ['Marketing','CEO'], secondary: ['Investor'] }, delayedQueue: []
  },
  viral_growth: {
    event: 'Product Hunt #1 — 50K signups in 24 hours, servers groaning',
    oracleSkip: true, marketSentiment: 'bullish',
    preMetrics: { growth: 45, technicalDebt: 40 },
    relevanceHints: { primary: ['CTO','CEO','Marketing'], secondary: ['PM'] },
    delayedQueue: [{ fireAtRound: 2, description: 'Infrastructure buckles under traffic spike', metrics: { technicalDebt: 20, morale: -8 }, severity: 'high', probability: 0.85 }]
  },
  exec_resignation: {
    event: 'CTO submits resignation effective Friday — cites burnout and broken promises',
    oracleSkip: true, marketSentiment: 'bearish', preMetrics: { morale: 45, technicalDebt: 50 },
    relevanceHints: { primary: ['CEO','CTO','Investor'], secondary: ['PM'] }, delayedQueue: []
  }
};
const body = $input.first().json;
const scenario = body.demoMode || body.scenario;
if (scenario && DEMO_SCENARIOS[scenario]) {
  const demo = DEMO_SCENARIOS[scenario];
  if (body.worldState?.company && demo.preMetrics) Object.assign(body.worldState.company, demo.preMetrics);
  return [{ json: { ...body, event: demo.event, demoConfig: demo, isDemoMode: true, marketSentiment: demo.marketSentiment } }];
}
return [{ json: { ...body, isDemoMode: false } }];

const body = $input.first().json.body || $input.first().json;
const budget = body.budget || 500000;
const runway = body.runway || 12;
const startupId = body.startupId || ('startup_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
const scenario = body.scenario || body.demoMode || 'competitor_50m';
const state = {
  company: { name: body.name || 'PulseAI', industry: body.industry || 'AI', idea: body.idea || 'Autonomous startup OS', phase: 'seed', budget, burnRate: Math.round(budget/runway), runway, mrr: Math.round(budget*0.015), arr: Math.round(budget*0.18), growth: 18, morale: 75, investorConfidence: 60, technicalDebt: 20, brandReputation: 45, productQuality: 55, marketFit: 40, teamSize: body.teamSize||10, growthStrategy: body.growthStrategy||'viral' },
  relationships: { 'CEO-CTO':'aligned','CEO-PM':'aligned','CEO-Finance':'neutral','CEO-Marketing':'aligned','CTO-PM':'tense','Finance-Marketing':'conflict' },
  influence: { CEO:85, CTO:70, PM:60, Marketing:55, Finance:65, Investor:90 },
  personalityVectors: { CEO:{riskTolerance:75,aggressiveness:80,optimism:85,paranoia:20,confidence:80}, CTO:{riskTolerance:30,aggressiveness:35,optimism:40,paranoia:60,confidence:70}, PM:{riskTolerance:50,aggressiveness:40,optimism:65,paranoia:35,confidence:60}, Marketing:{riskTolerance:70,aggressiveness:75,optimism:80,paranoia:25,confidence:70}, Finance:{riskTolerance:20,aggressiveness:30,optimism:30,paranoia:70,confidence:85}, Investor:{riskTolerance:50,aggressiveness:60,optimism:35,paranoia:75,confidence:90} },
  agentMemory: { CEO:{recentConcerns:[],pastDecisions:[],currentStance:'Growth first',credibility:75,wins:0,losses:0,failedPredictions:[],learnings:[]}, CTO:{recentConcerns:[],pastDecisions:[],currentStance:'Scale carefully',credibility:70,wins:0,losses:0,failedPredictions:[],warnings:[],learnings:[]}, PM:{recentConcerns:[],pastDecisions:[],currentStance:'Users first',credibility:60,wins:0,losses:0,failedPredictions:[],learnings:[]}, Marketing:{recentConcerns:[],pastDecisions:[],currentStance:'Brand now',credibility:55,wins:0,losses:0,failedPredictions:[],learnings:[]}, Finance:{recentConcerns:[],pastDecisions:[],currentStance:'Extend runway',credibility:65,wins:0,losses:0,failedPredictions:[],budgetWarnings:[],learnings:[]}, Investor:{recentConcerns:[],pastDecisions:[],currentStance:'Need moat',credibility:90,wins:0,losses:0,failedPredictions:[],learnings:[]} },
  delayedConsequences: [], roadmap: [], eventHistory: [], decisionHistory: [], simulationRound: 1, lastEvent: 'Demo initialized', status: 'OPERATING', marketSentiment: 'neutral'
};
return [{ json: { startupId, worldState: state, scenario, demoMode: scenario, event: null, agentPrompt: `COMPANY: ${state.company.name}. Leadership war room. React to imminent crisis.` } }];

const item = $input.first().json;
const worldState = item.worldState;
const userEvent = item.event || 'Routine operations continue';
const c = worldState.company;
const isDemo = item.isDemoMode;
const demo = item.demoConfig || {};
let oracleOutput = null;
if (isDemo && demo.oracleSkip) {
  oracleOutput = { event: null, category: 'market', severity: 'medium', marketSentiment: demo.marketSentiment || 'neutral', relevanceHints: demo.relevanceHints || { primary: ['CEO'], secondary: [] } };
  if (demo.delayedQueue?.length) {
    worldState.delayedConsequences = [...(worldState.delayedConsequences || []), ...demo.delayedQueue.map(dc => ({ ...dc, queuedAtRound: worldState.simulationRound || 1, source: 'demo' }))];
  }
}
worldState.marketSentiment = item.marketSentiment || worldState.marketSentiment || 'neutral';
const oraclePrompt = `Market Oracle. Company: ${c.name} | phase: ${c.phase} | debt: ${c.technicalDebt} | morale: ${c.morale} | runway: ${c.runway}mo
User event: "${userEvent}"
Generate ONE external market event (max 18 words). JSON only:
{"event":"...","category":"competitor|market|regulatory|talent|infrastructure|pr","severity":"low|medium|high|critical","marketSentiment":"bullish|neutral|bearish|panic","relevanceHints":{"primary":["CTO"],"secondary":["CEO"]}}`;
return [{ json: { ...item, worldState, event: userEvent, userEvent, oracleOutput, needsOracle: !oracleOutput, oraclePrompt, isDemoMode: isDemo } }];

const raw = $input.first().json;
let item = raw;
if (!raw.worldState) {
  try { item = { ...$('Prepare Round Context').first().json, output: raw.output, ...raw }; } catch(e) {}
}
const userEvent = item.userEvent || item.event;
let oracle = item.oracleOutput;
if (item.output) {
  const o = item.output;
  oracle = typeof o === 'string' ? JSON.parse(o) : o;
}
if (!oracle && item.needsOracle === false) {
  oracle = { event: null, marketSentiment: item.marketSentiment || 'neutral', relevanceHints: item.demoConfig?.relevanceHints };
}
const oracleEvent = oracle?.event;
const combinedEvent = oracleEvent && !item.isDemoMode ? `${userEvent}. Meanwhile: ${oracleEvent}` : userEvent;
if (oracle?.marketSentiment) item.worldState.marketSentiment = oracle.marketSentiment;
item.worldState.lastOracleEvent = oracleEvent || null;
const pendingEvents = worldState.pendingEvents || [];
