const item = $input.first().json;
const ws = item.worldState;

const round = ws.simulationRound || 1;
const pending = ws.delayedConsequences || [];

const due = [];
const future = [];

for (const c of pending) {
  if ((c.fireAtRound || 999) <= round) {
    due.push(c);
  } else {
    future.push(c);
  }
}

const company = { ...(ws.company || {}) };

// Only clamp bounded metrics; financials should change freely
const boundedMetrics = [
  'morale', 'investorConfidence', 'technicalDebt',
  'brandReputation', 'productQuality', 'marketFit'
];

for (const c of due) {
  const metrics = c.metrics || {};
  for (const [k, v] of Object.entries(metrics)) {
    if (typeof company[k] !== 'number') continue;
    if (boundedMetrics.includes(k)) {
      company[k] = Math.max(0, Math.min(100, company[k] + v));
    } else {
      company[k] += v;
    }
  }
}

ws.company = company;
ws.delayedConsequences = future;

return [{
  json: {
    ...item,
    worldState: ws,
    firedConsequences: due
  }
}];
